insert into app.product_translations (product_id, locale, name, description, origin_text, storage_text, sourcing_text, ingredients_text) values
  ('fb990059-cb44-5b34-bc82-7eec3d32e4c4', 'en-GB', 'Organic Red Tomatoes', 'Sweet, vine-ripened organic tomatoes packed with rich sun-kissed flavour. Perfect for fresh salads and slow-roast pasta sauces.', 'Kent, United Kingdom', null, null, null),
  ('e5468bb1-519a-5159-a1d7-6b45e091a60f', 'en-GB', 'Fresh Bananas', 'Creamy, sweet, and naturally ripened bananas. Ideal for breakfast bowls, smoothies, and snacking.', 'Fairtrade Certified', null, null, null),
  ('6616eb71-acd1-5ee2-9b40-aeef29fafd6a', 'en-GB', 'Organic Broccoli', 'Crisp green florets packed with wholesome vitamins and minerals. Steams tender in minutes.', 'Lincolnshire, United Kingdom', null, null, null),
  ('c50ec2e6-ba85-570e-8693-9796fe0d7e01', 'en-GB', 'Fresh Strawberries', 'Juicy, fragrant strawberries picked at the height of summer sweetness. Perfect with cream or yoghurt.', 'Herefordshire, United Kingdom', null, null, null),
  ('311d91ba-0cc2-5dc4-9294-02e1bf652ee1', 'en-GB', 'Farm Fresh Eggs', 'Free-range brown eggs with vibrant golden yolks from pasture-roaming hens in eco-friendly carton.', 'Suffolk Pastures', null, null, null),
  ('d7665b9c-d7ab-591d-b99f-35b4be34eb73', 'en-GB', 'French Butter Croissants', 'Handcrafted golden flaky croissants layered with pure cultured Normandy butter. Flaky outside, tender and buttery inside.', 'FreshMart Artisan Bakery', null, null, null),
  ('a7254c12-2d92-500f-ae28-5cb5a8a8289e', 'en-GB', 'Artisan Sourdough Loaf', 'Naturally fermented 36-hour slow sourdough bread with a deep caramelized blistered crust and open airy crumb.', 'Stoneground Heritage Grains', null, null, null),
  ('7bd7619d-7846-5498-979b-a16e2534bea7', 'en-GB', 'Organic Whole Farm Milk', 'Creamy, unhomogenized farm-fresh whole milk delivered in chilled glass bottles from free-roaming jersey cows.', 'Cloverdale Pastures', null, null, null),
  ('4a962406-a20c-555d-9a1a-081ee4a0470d', 'en-GB', 'Aged Farmhouse Cheddar', 'Traditional clothbound cheddar aged for 18 months with delicate tyrosine crystals and rich nutty flavor notes.', 'Somerset Heritage Dairy', null, null, null),
  ('d1d74215-a041-58c4-8370-77eabedb2bf1', 'en-GB', 'Pasture Raised Eggs', 'Vibrant deep-amber yolks packed with natural Omega-3 fatty acids from hens free to forage green herbal pastures.', 'Pasture Hills Organic', null, null, null),
  ('425095a7-22e4-52c0-af1a-6921ca2bbb7d', 'en-GB', 'Basmati Rice Aged', 'Aromatic extra-long grain aged basmati rice that cooks fluffy and separate every time.', 'Himalayan Foothills', null, null, null),
  ('af9c4fd7-cf99-5099-8029-b19e7191b6a4', 'en-GB', 'Pure Sunflower Oil', 'Light, golden refined sunflower oil with a high smoke point. Ideal for everyday frying and cooking.', 'Pure Cold Pressed', null, null, null),
  ('d4e057fb-21f4-5f03-81e1-acc569155ef2', 'en-GB', 'Fresh Baby Spinach', 'Tender baby spinach leaves washed and ready to enjoy in salads or sautéed with garlic.', 'Norfolk, United Kingdom', null, null, null),
  ('4c686a2e-87e0-5956-b340-c1dc7e5259e1', 'en-GB', 'Prime Chicken Breast', 'Succulent skinless and boneless chicken breast fillets from high-welfare British farms.', 'British Red Tractor Farm Assured', null, null, null),
  ('4ce3b012-1ad0-54bb-af48-d7d90a93e165', 'en-GB', 'California Almonds', 'Whole natural raw almonds packed with protein, vitamin E, and wholesome fiber.', 'California Premium Harvest', null, null, null),
  ('d4838900-3c4d-5d09-849e-09b3d2ea5772', 'en-GB', 'Extra Virgin Olive Oil', 'Single-estate cold pressed extra virgin olive oil with peppery finish and emerald hue. First cold extraction.', 'Tuscany, Italy', null, null, null),
  ('96af9e0b-9cba-5d20-91d4-4bb9cd4c83a3', 'en-GB', 'Fresh Hass Avocados', 'Buttery, nutrient-dense Hass avocados with rich texture. Perfect for artisanal toast and guacamole.', 'Michoacán Harvest', null, null, null),
  ('06df43f1-80c8-507d-a16f-36d14068e100', 'en-GB', 'Fresh Salmon Steaks', 'Sustainably farmed Scottish salmon fillets rich in heart-healthy Omega-3 fatty acids with delicate marbling.', 'Loch Fyne, Scotland', null, null, null),
  ('bb2745bb-7854-52ba-83fa-ed8c20d4c8e9', 'en-GB', 'Raw Organic Wildflower Honey', 'Unpasteurized pure raw wildflower blossom honey harvested sustainably. Retains all natural pollen and enzymes.', 'Cotswolds Apiaries', null, null, null),
  ('5f6d88de-2ba6-5734-b3fa-697f300067cc', 'en-GB', 'Cold-Pressed Citrus Juice', '100% pure cold-pressed Valencia oranges and fresh mint. Never heated, no added sugars or preservatives.', 'Valencia Sun Harvest', null, null, null),
  ('a663a00a-ee37-5195-a807-ae197361349c', 'en-GB', 'Crisp Pink Lady Apples', 'Sweet, effervescent crunch with a delightful rosy blush. High in pectin and dietary fiber.', 'Kentish Orchards, UK', 'Keep refrigerated in the crisper drawer to maintain crunchiness for up to 3 weeks.', 'Hand-picked at peak maturity from family-owned orchards in Kent.', null),
  ('8ef7688b-a563-5944-96af-846dc2ec6f72', 'en-GB', 'Heirloom Rainbow Carrots', 'Vibrant purple, yellow, and deep orange heritage carrots sweet enough to eat raw with hummus or slow-roasted.', 'Norfolk Earth Farms', 'Remove green tops and store in a breathable bag in your refrigerator vegetable drawer.', 'Grown without synthetic pesticides on regenerative soil in Norfolk.', null),
  ('7925f063-7903-561f-a93c-f90351d5eed8', 'en-GB', 'Cold-Pressed Green Glow Smoothie', 'Crisp green apple, wild cucumber, leafy spinach, ginger, and key lime cold-pressed under 4°C.', 'FreshMart Juicery', 'Keep refrigerated below 5°C. Consume within 3 days after opening.', 'Pressed daily using our zero-heat hydraulic press in small batches.', null),
  ('81955ebd-23ba-5111-92a9-360adb739314', 'en-GB', 'Organic Salted Farm Butter', 'Churned slowly from grass-fed Guernsey cow cream with crystals of Maldon sea salt flakes.', 'Dorset Creamery', 'Store chilled. Bring to room temperature 15 minutes before spreading.', '100% pasture-grazed dairy cows enjoying coastal British meadows.', null),
  ('681e585d-f782-59bc-aa49-e91266408a94', 'en-GB', 'Rosemary & Sea Salt Focaccia', 'Airy, olive oil-drenched traditional Italian flatbread topped with garden rosemary sprigs and flaky sea salt.', 'FreshMart Artisan Bakery', 'Enjoy fresh within 48 hours or freeze sliced. Warm in oven for 5 minutes at 180°C.', 'Made with stoneground unbleached organic flour and extra virgin olive oil.', null),
  ('0eba32b2-d9e7-5c2f-b5fe-cff90fef1ebb', 'en-GB', 'Wild Atlantic Cod Fillets', 'Thick, pearlescent white cod flakes with a clean, mild ocean taste. Exceptional pan-seared or baked.', 'North Sea Sustainable Fishery', 'Keep refrigerated between 0-4°C. Consume within 2 days or freeze immediately.', 'Line-caught by certified sustainable fisheries adhering to strict Marine Stewardship quotas.', null),
  ('0bcbfe40-bc58-5722-91e1-823dfbc53804', 'en-GB', 'Aachi Madras Sambar Powder', 'Authentic South Indian aromatic sambar powder blended with coriander, red chilli, fenugreek, cumin and curry leaves.', 'Tamil Nadu, India', null, null, null),
  ('3082ac22-f770-548f-96ba-3a0130c2d13e', 'en-GB', 'MDH Deggi Mirch Natural Red Chilli', 'A unique blend of specially selected Indian red chillies that imparts rich natural red color and mild warmth without scorching heat.', 'Delhi, India', null, null, null),
  ('2b315a5d-65ee-5d34-a52c-48c21cac9b1c', 'en-GB', 'Royal Premium Toor Dal (Oodhaiyam)', 'Pure unpolished protein-rich yellow split pigeon peas. Cooks smoothly into creamy dal, sambar, and rasam.', 'Maharashtra, India', null, null, null),
  ('fd15bbd6-efa3-5b5e-b206-e53ad4833b96', 'en-GB', 'Urad Dal White Gota (Whole)', 'Premium whole dehusked white urad dal. Grinds into fluffy, airy batter for soft idlis, crisp dosas, and golden medu vadas.', 'Andhra Pradesh, India', null, null, null),
  ('8b6841db-162f-5df0-8de3-905aa054698b', 'en-GB', 'Aashirvaad Superior MP Chakki Atta', '100% pure whole wheat stone-ground chakki fresh atta from the golden amber grains of MP. Makes softer, fluffier rotis that stay tender.', 'Madhya Pradesh, India', null, null, null),
  ('e7124ef5-d3a4-5acd-b1f0-91adb4a44b20', 'en-GB', 'Haldiram''s Traditional Gulab Jamun', 'Melt-in-mouth cottage cheese dumplings soaked in fragrant rose water and cardamom sugar syrup.', 'Nagpur, India', null, null, null),
  ('3833fefc-6b1f-5c3e-b8cb-96ada111640c', 'en-GB', 'Grand Sweets Madras Mixture', 'Legendary crunchy Chennai savory mix with boondi, sev, fried curry leaves, cashews, and roasted peanuts tossed in special spice salt.', 'Chennai, India', null, null, null),
  ('24f70ec5-c2e5-51ed-82ed-18b2063c0b62', 'en-GB', 'Shana Traditional Malabar Paratha', 'Multi-layered flaky, crispy Kerala flatbread. Toast directly on a hot tawa in 3 minutes for authentic restaurant-style parottas.', 'Kerala, India', null, null, null),
  ('5072d76e-b10e-55fe-9d71-58b98197093a', 'en-GB', 'Daily Fresh Grated Coconut (Frozen)', 'Freshly shredded mature coconuts flash-frozen within hours of plucking. Retains natural sweet coconut milk taste for chutneys and avial.', 'Kerala, India', null, null, null),
  ('df8d43bd-4aca-5f5b-a36f-b401d51449fc', 'en-GB', 'Deepam Pure Pooja Oil (Panchadeepam Blend)', 'Proprietary sacred blend of 5 sacred oils (sesame, neem, mahua, castor, and pure cow ghee) formulated for deep, soot-free, tranquil lamp flame.', 'Tamil Nadu, India', null, null, null),
  ('1672f1c8-1fef-525f-a839-fd87ad92d8e3', 'en-GB', 'Traditional Brass Kamakshi Deepam Lamp', 'Hand-crafted solid brass traditional Kamakshi Vilakku with intricate Goddess Lakshmi embossing for auspicious home poojas and festivals.', 'Kumbakonam, India', null, null, null),
  ('d02ec43e-f94c-55af-86cd-74410f241905', 'en-GB', 'Diamond Induction Base Idly Pot (16 Pits)', 'Heavy gauge stainless steel idly pot with steam vent and 4 tier plates to steam 16 soft, pillowy idlis simultaneously.', 'Tamil Nadu, India', null, null, null),
  ('1688bcbe-a03f-513b-bef1-fe69fabe5cd6', 'en-GB', 'Prestige Deluxe Stainless Steel Pressure Cooker 5L', 'High-grade stainless steel pressure cooker with pressure indicator, safety valve and durable alpha induction base.', 'Bangalore, India', null, null, null),
  ('660ec7ca-0ed8-5126-b7a7-b28f56989f4e', 'en-GB', 'Himalaya Purifying Neem Face Wash', 'Herbal soap-free formulation with pure organic neem and turmeric that clears pimples, excess oil and purifies pores gently.', 'Bangalore, India', null, null, null),
  ('9ceaddbd-a424-53c7-b700-e07486f7cd77', 'en-GB', 'Parachute 100% Pure Coconut Hair Oil', 'Made from the finest sun-dried coconuts of coastal India. 100% pure coconut oil without additives, mineral oil or preservatives.', 'Kerala, India', null, null, null),
  ('464b7a7d-fd59-54ce-9504-dce6d2b926c0', 'en-GB', 'India Gate Classic Aged Basmati Rice', 'Extra-long pearlescent slender grains that elongate up to twice their length on cooking with non-sticky fluffiness and royal aroma.', 'Punjab, India', null, null, null),
  ('204127a6-6ad3-5640-9abd-c0701f37534f', 'en-GB', 'Pure Desi Cow Ghee 500ml', '', null, null, null, null),
  ('ca3ac25d-c674-5451-b08e-3310231ffc86', 'en-GB', 'Aashirvaad Shudh Chakki Atta 10kg', '', null, null, null, null)
